$ErrorActionPreference='Stop'
$dir=(Get-Location).Path
$base=Get-Content -LiteralPath (Join-Path $dir 'asoud-organizational-structure-v1.svg') -Raw -Encoding UTF8
$shell=$base.Substring(0,$base.IndexOf('<!-- page header -->'))

function New-OrganizationPage($file,$title,$subtitle,$listTitle,$rows,$formTitle,$fields,$note,$step='') {
  $rowSvg=''; $y=505
  foreach($r in $rows){
    $rowSvg+="<rect x='820' y='$y' width='1000' height='72' rx='8' fill='#fff' stroke='#dfe5ee'/><circle cx='1780' cy='$($y+36)' r='18' fill='#edf3ff'/><text x='1780' y='$($y+42)' class='t' fill='#155bd7' font-size='12' font-weight='800' text-anchor='middle'>$($r.Substring(0,1))</text><text x='1745' y='$($y+29)' class='t d' font-size='13' font-weight='700' text-anchor='end'>$r</text><text x='1745' y='$($y+50)' class='t m' font-size='10' text-anchor='end'>فعال • آخرین ویرایش امروز</text>"
    $y+=84
  }
  $fieldSvg=''; $fy=510
  foreach($f in $fields){
    $fieldSvg+="<text x='650' y='$fy' class='t m' font-size='10' text-anchor='end'>$($f[0])</text><rect x='92' y='$($fy+10)' width='558' height='40' rx='8' fill='#f8fafd' stroke='#dfe5ee'/><text x='625' y='$($fy+35)' class='t d' font-size='12' font-weight='600' text-anchor='end'>$($f[1])</text>"
    $fy+=70
  }
  $stepSvg=if($step){"<rect x='92' y='398' width='558' height='48' rx='8' fill='#edf3ff'/><text x='625' y='427' class='t' fill='#155bd7' font-size='12' font-weight='700' text-anchor='end'>$step</text>"}else{''}
  $svg=$shell+@"
<!-- page header -->
<rect y="182" width="1920" height="123" fill="#fff"/>
<text x="1848" y="222" class="t d" font-size="26" font-weight="800" text-anchor="end">$title</text>
<text x="1848" y="245" class="t m" font-size="12" text-anchor="end">$subtitle</text>
<rect x="72" y="205" width="145" height="42" rx="8" fill="#155bd7"/><text x="197" y="231" class="t" fill="#fff" font-size="12" font-weight="700" text-anchor="end">+ ثبت مورد جدید</text>
<g class="t d" font-size="13" text-anchor="middle"><text x="1770" y="286">نمای ساختار</text><text x="1605" y="286">هلدینگ</text><text x="1460" y="286">شرکت‌ها</text><text x="1320" y="286">شعب</text><text x="1135" y="286">روابط وابستگی</text></g>
<rect x="70" y="327" width="1780" height="650" rx="10" fill="#fff" stroke="#dfe5ee"/>
<text x="1815" y="369" class="t d" font-size="16" font-weight="800" text-anchor="end">$listTitle</text>
<rect x="820" y="393" width="1000" height="42" rx="8" fill="#f8fafd" stroke="#dfe5ee"/><text x="1790" y="419" class="t m" font-size="11" text-anchor="end">جست‌وجو و فیلتر...</text>
$rowSvg
<!-- registration drawer -->
<rect x="70" y="327" width="620" height="650" rx="10" fill="#fff" stroke="#dfe5ee" filter="url(#s)"/>
<text x="650" y="369" class="t d" font-size="17" font-weight="800" text-anchor="end">$formTitle</text>
<path d="M102 354l14 14m0-14l-14 14" stroke="#64748b" stroke-width="2"/><line x1="92" y1="385" x2="668" y2="385" stroke="#dfe5ee"/>
$stepSvg$fieldSvg
<rect x="92" y="844" width="558" height="56" rx="8" fill="#edf3ff"/><text x="625" y="868" class="t d" font-size="11" font-weight="700" text-anchor="end">نکته کنترلی</text><text x="625" y="887" class="t m" font-size="9" text-anchor="end">$note</text>
<rect x="92" y="918" width="145" height="42" rx="8" fill="#155bd7"/><text x="217" y="944" class="t" fill="#fff" font-size="12" font-weight="700" text-anchor="end">ثبت و ادامه</text><rect x="249" y="918" width="105" height="42" rx="8" fill="#fff" stroke="#b9c7dc"/><text x="332" y="944" class="t d" font-size="12" text-anchor="end">انصراف</text>
<text x="960" y="1058" class="t m" font-size="10" text-anchor="middle">ASOUD ERP — Organization Forms v1 — پوسته اصلی ثابت است</text></svg>
"@
  [IO.File]::WriteAllText((Join-Path $dir $file),$svg,[Text.UTF8Encoding]::new($false))
}

New-OrganizationPage 'asoud-holdings-with-create-form-v1.svg' 'هلدینگ‌ها' 'مدیریت شخصیت مادر و دامنه گزارش‌های تلفیقی' 'فهرست هلدینگ‌ها' @('گروه آسود','گروه سرمایه‌گذاری نمونه') 'ثبت هلدینگ جدید' @(@('نام هلدینگ','گروه آسود'),@('نوع شخصیت','حقوقی⌄'),@('شناسه ملی','۱۴۰۰۱۲۳۴۵۶۷'),@('ارز گزارش تلفیقی','ریال ایران⌄')) 'عضویت شرکت‌ها پس از ثبت هلدینگ و با رویداد حسابرسی انجام می‌شود.'
